class Solution:
    def minMoves(self, balance):
        total = sum(balance)
        if total < 0:
            return -1
        if all(x >= 0 for x in balance):
            return 0
        n = len(balance)
        p = balance.index(min(balance))
        need = -balance[p]
        sup = []
        for i in range(n):
            if i == p:
                continue
            d = min((p - i) % n, (i - p) % n)
            sup.append((d, balance[i]))
        sup.sort()
        moves = 0
        for d, amt in sup:
            take = min(amt, need)
            moves += take * d
            need -= take
            if need == 0:
                break
        return moves

