class Solution {
public:
    long long minMoves(vector<int>& balance) {
        long long total = 0;
        for (int x : balance) total += x;
        if (total < 0) return -1;
        bool neg = false;
        for (int x : balance) if (x < 0) neg = true;
        if (!neg) return 0;
        int n = balance.size(), p = 0;
        for (int i = 0; i < n; i++) if (balance[i] < 0) p = i;
        long long need = -(long long)balance[p];
        vector<pair<long long, long long>> sup;
        for (int i = 0; i < n; i++) {
            if (i == p) continue;
            long long d = min((p - i + n) % n, (i - p + n) % n);
            sup.push_back({d, balance[i]});
        }
        sort(sup.begin(), sup.end());
        long long moves = 0;
        for (auto& [d, amt] : sup) {
            long long take = min(amt, need);
            moves += take * d;
            need -= take;
            if (need == 0) break;
        }
        return moves;
    }
};

c.java:
class Solution {
    public long minMoves(int[] balance) {
        long total = 0;
        boolean neg = false;
        for (int x : balance) { total += x; if (x < 0) neg = true; }
        if (total < 0) return -1;
        if (!neg) return 0;
        int n = balance.length, p = 0;
        for (int i = 0; i < n; i++) if (balance[i] < 0) p = i;
        long need = -(long) balance[p];
        long[][] sup = new long[n - 1][2];
        int idx = 0;
        for (int i = 0; i < n; i++) {
            if (i == p) continue;
            long d = Math.min((p - i + n) % n, (i - p + n) % n);
            sup[idx][0] = d;
            sup[idx][1] = balance[i];
            idx++;
        }
        Arrays.sort(sup, (a, b) -> Long.compare(a[0], b[0]));
        long moves = 0;
        for (long[] s : sup) {
            long take = Math.min(s[1], need);
            moves += take * s[0];
            need -= take;
            if (need == 0) break;
        }
        return moves;
    }
}

