var minMoves = function(balance) {
    const total = balance.reduce((a, b) => a + b, 0);
    if (total < 0) return -1;
    if (balance.every(x => x >= 0)) return 0;
    const n = balance.length;
    const p = balance.indexOf(Math.min(...balance));
    let need = -balance[p];
    const sup = [];
    for (let i = 0; i < n; i++) {
        if (i === p) continue;
        const d = Math.min((p - i + n) % n, (i - p + n) % n);
        sup.push([d, balance[i]]);
    }
    sup.sort((a, b) => a[0] - b[0]);
    let moves = 0;
    for (const [d, amt] of sup) {
        const take = Math.min(amt, need);
        moves += take * d;
        need -= take;
        if (need === 0) break;
    }
    return moves;
};
